        const [output, runeId] = mismatch.split('|');
        return refuse('RUNE_ALLOCATION_MISMATCH', `Output ${output} would receive ${(actual.get(mismatch) ?? 0n).toString()} of rune ${runeId}, not the ${(planned.get(mismatch) ?? 0n).toString()} stated.`);
