    if (status === 'UNCLOSED')
        return refuse('UNCLOSED_SIGHASH', 'The buyer signature does not commit to the whole recovery.');
    if (status !== 'VALID')
        return refuse('SIGNATURE_INVALID', 'The buyer signature does not verify against the recovery key.');
