        if (value === null) {
            return refuse('INPUT_VALUE_UNKNOWN', `The value of input ${i} could not be read, so the sat flow invariant cannot be evaluated.`);
        }
        inputsAhead += value;
    }
    const offeredValue = parseSats(transaction.inputs[n]?.valueSats);
    if (offeredValue === null) {
        return refuse('INPUT_VALUE_UNKNOWN', 'The value of the offered output could not be read, so the sat flow invariant cannot be evaluated.');
    }
    let outputsAhead = 0n;
    for (let i = 0; i < n; i += 1) {
        const value = parseSats(transaction.outputs[i]?.valueSats);
        if (value === null) {
            return refuse('MALFORMED_TRANSACTION', `Output ${i} does not carry an exact decimal value.`);
        }
        outputsAhead += value;
    }
    if (outputsAhead < inputsAhead + offeredValue) {
        return refuse('SAT_FLOW_SHORTFALL', 'The outputs ahead of the seller payment do not absorb the whole range the offered output occupies, ' +
            'so part of the asset would land inside the payment going back to the seller.');
    }
